-- +goose Up
-- 1. Create the Wards Table
CREATE TABLE IF NOT EXISTS wards (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    code VARCHAR(10) NOT NULL,
    lga_id INTEGER NOT NULL REFERENCES lgas(id) ON DELETE CASCADE,
    lga_name VARCHAR(255) NOT NULL,
    senatorial_district_id INTEGER REFERENCES senatorial_districts(id) ON DELETE CASCADE,
    senatorial_district_name VARCHAR(255),
    federal_constituency_id INTEGER REFERENCES federal_constituencies(id) ON DELETE CASCADE,
    federal_constituency_name VARCHAR(255),
    state_constituency_id INTEGER REFERENCES state_constituencies(id) ON DELETE CASCADE,
    state_constituency_name VARCHAR(255),
    state_id INTEGER NOT NULL REFERENCES c_states(id) ON DELETE CASCADE,
    state_name VARCHAR(255) NOT NULL,
    mongo_id VARCHAR(50),
    status VARCHAR(50) DEFAULT 'active',
    polling_units_count INTEGER DEFAULT 0
);

CREATE INDEX idx_wards_name ON wards (name);
CREATE INDEX idx_wards_lga_id ON wards (lga_id);
CREATE INDEX idx_wards_senatorial_district_id ON wards (senatorial_district_id);
CREATE INDEX idx_wards_federal_constituency_id ON wards (federal_constituency_id);
CREATE INDEX idx_wards_state_constituency_id ON wards (state_constituency_id);
CREATE INDEX idx_wards_state_id ON wards (state_id);

